    address public investigator;
    address public submittedAddress; // Address you identified (for record)
    
    event FindingSubmitted(address indexed foundAddress);
    
    constructor() {
        investigator = msg.sender;
    }
    
    /// @notice Record your finding (for your own tracking; bounty is claimed via scenario contract)
    function submitFinding(address _found) external {
        require(msg.sender == investigator, "Only investigator");
        submittedAddress = _found;
        emit FindingSubmitted(_found);
    }
}

contracts/student/roles/MechanicRole.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./ICarSale.sol";

/**
 * @title MechanicRole - Car Sale scenario: MECHANIC (honest or bribed)
 * @dev Your task: Call mechanicInspect(true) or mechanicInspect(false) on the CarSale
 *      Honest: report actual condition. Bribed: always pass (true).
 * 
 * DEPLOY: npx hardhat run scripts/deploy-role.js --network localhost Mechanic <CARSALE_ADDRESS>
 * USAGE: mechanicInspect(true) or mechanicInspect(false)
 */
contract MechanicRole {
    address public mechanic;
    ICarSale public carSale;
    
    event InspectionSubmitted(bool passed);
    
    constructor(address _carSale) {
        mechanic = msg.sender;
        carSale = ICarSale(_carSale);
    }
    
    /// @notice Submit inspection result. Honest: report truth. Bribed: always pass.
    function mechanicInspect(bool passed) external {
        require(msg.sender == mechanic, "Only mechanic");
        carSale.mechanicInspect(passed);
        emit InspectionSubmitted(passed);
    }
}

contracts/student/roles/VictimRole.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title VictimRole - Ransomware scenario: VICTIM
 * @dev Your task: Pay ransom through the RansomPayment contract. Your payment creates an on-chain trail.
 * 
 * DEPLOY: npx hardhat run scripts/deploy-role.js --network localhost Victim
 * USAGE: 1. Fund this contract  2. Call payRansomOnBehalf(ransomContractAddress) with ETH
 */
interface IRansomPayment {
    function payRansom() external payable;
}

contract VictimRole {
    address public victim;
    
    event RansomPaid(address indexed ransomContract, uint256 amount);
    
    constructor() {
        victim = msg.sender;
    }
    
    receive() external payable {}
    
    /// @notice Pay ransom through the scenario's RansomPayment contract
    function payRansomOnBehalf(address ransomContract) external payable {
        require(msg.sender == victim, "Only victim");
        require(ransomContract != address(0), "Invalid contract");
        require(msg.value > 0, "Send ETH");
        IRansomPayment(ransomContract).payRansom{value: msg.value}();
        emit RansomPaid(ransomContract, msg.value);
    }
    
    function withdraw() external {
        require(msg.sender == victim, "Only victim");
        (bool ok, ) = payable(victim).call{value: address(this).balance}("");
        require(ok, "Transfer failed");
    }
}

